import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        Path root = Files.createTempDirectory("walkdemo");
        Files.createDirectories(root.resolve("a/sub"));
        Files.createDirectories(root.resolve("b"));
        Files.writeString(root.resolve("a/f1.txt"), "hello");
        Files.writeString(root.resolve("a/sub/f2.txt"), "world!!");
        Files.writeString(root.resolve("b/f3.txt"), "x");

        // depth-limited walk: root itself is depth 0
        long d1 = Files.walk(root, 1).count();
        long all = Files.walk(root).count();
        System.out.println("entries at depth<=1 (root + a + b)         : " + d1);
        System.out.println("entries in the whole tree                   : " + all);

        // directory stream lists ONLY direct children
        long direct;
        try (DirectoryStream<Path> ds = Files.newDirectoryStream(root)) {
            direct = 0;
            for (Path ignored : ds) direct++;
        }
        System.out.println("newDirectoryStream direct children only      : " + direct);

        // attributes in one call
        Path f = root.resolve("a/sub/f2.txt");
        BasicFileAttributes at = Files.readAttributes(f, BasicFileAttributes.class);
        System.out.println("f2.txt size / isDirectory / isRegularFile     : "
                + at.size() + " / " + at.isDirectory() + " / " + at.isRegularFile());
        System.out.println("matches \"world!!\" length                    : " + (at.size() == 7));

        // collect only *.txt under the whole tree, sorted for determinism
        List<String> names = new ArrayList<>();
        try (var s = Files.walk(root)) {
            s.filter(x -> x.toString().endsWith(".txt")).forEach(x -> names.add(x.getFileName().toString()));
        }
        names.sort(String::compareTo);
        System.out.println("txt files found (sorted)                     : " + names);

        // delete requires post-order: files first, then the directory itself
        try (var s = Files.walk(root)) {
            s.sorted((x, y) -> y.getNameCount() - x.getNameCount())
             .forEach(x -> { try { Files.delete(x); } catch (IOException e) { throw new RuntimeException(e); } });
        }
        System.out.println("tree removed successfully                    : " + !Files.exists(root));
    }
}
